#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>
int main(void) {
    size_t n = 256UL << 20;          // 256MB
    char *buf = malloc(n);
    memset(buf, 'A', n);             // 부모가 페이지를 실제로 채운다
    if (fork() == 0) {               // 페이지는 복사되지 않고 읽기 전용으로 공유
        buf[0] = 'B';                // 쓰기 → 폴트 → 이 페이지 하나만 복사
        printf("child:  %c\n", buf[0]);   // B
        _exit(0);
    }
    wait(NULL);
    printf("parent: %c\n", buf[0]);       // A, 부모 쪽은 그대로
    return 0;
}

#include <fcntl.h>
#include <stdio.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
int main(int argc, char *argv[]) {
    int fd = open(argv[1], O_RDONLY);
    struct stat st;
    fstat(fd, &st);
    char *p = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    // 여기까지는 파일 내용을 하나도 읽지 않았다
    long lines = 0;
    for (off_t i = 0; i < st.st_size; i++)  // 처음 닿는 페이지마다 페이지 폴트 → 요구 페이징
        if (p[i] == '\n') lines++;
    printf("%ld lines\n", lines);
    munmap(p, st.st_size);
    close(fd);
    return 0;
}
